def align_runtime_hnsw_index(apps, schema_editor):
    """Point the active HNSW index at the column the configured runtime uses.

    The model declares the index on `vector` (1024 dimensions); any other
    configured dimension stores its vectors in a different column.
    """
    if schema_editor.connection.vendor != "postgresql":
        return
    try:
        from documents.services.embedding_runtime_config import load_embedding_runtime

        dimension = load_embedding_runtime(scope="production").dimension
    except Exception:
        dimension = 1024
    column_name = DIMENSION_COLUMNS.get(dimension, "vector")
    if column_name == "vector":
        return
    ChunkEmbedding = apps.get_model("documents", "ChunkEmbedding")
    table = schema_editor.quote_name(ChunkEmbedding._meta.db_table)
    column = schema_editor.quote_name(column_name)
    index = schema_editor.quote_name(ACTIVE_HNSW_INDEX)
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(f"DROP INDEX IF EXISTS {index}")
        cursor.execute(
            f"CREATE INDEX {index} ON {table} USING hnsw "
            f"({column} vector_ip_ops) WITH (m = 16, ef_construction = 64)"
        )


